"""Small Studio control for creating a separately reviewed scene draft."""

SCENE_CONTROLS = r"""<dialog id="sceneDialog" aria-labelledby="sceneTitle"><div class="modal-head"><h2 id="sceneTitle">Revise one scene</h2><button class="close" type="button" id="sceneClose" aria-label="Close scene revision">×</button></div><form id="sceneForm"><div class="modal-body"><p class="sub">A saved edit creates a separate draft. The current video and its approvals stay unchanged; the new draft needs script and preview review.</p><p class="sub" id="sceneSheetHint" style="display:none;margin:12px 0 4px">Click a scene below (or pick it from the list) to edit it.</p><div id="sceneSheetWrap" style="position:relative;display:none;margin-top:4px"><img id="sceneSheet" alt="Current storyboard contact sheet" style="display:block;width:100%;height:auto;border-radius:8px"><div id="sceneTiles" style="position:absolute;inset:0;display:grid;grid-template-columns:repeat(4,1fr);align-content:start"></div></div><div id="sceneDirection" class="notice" role="status" style="overflow-wrap:anywhere"></div><label>Scene<select id="sceneSelect" required></select></label><label>Narration<textarea id="sceneNarration" required></textarea></label><label>Visual layout<select id="sceneLayout"><option value="flow_diagram">Flow diagram</option><option value="comparison">Comparison</option><option value="timeline">Timeline</option><option value="source_card">Source card</option><option value="terminal">Terminal</option></select></label><label>Visual subject<input id="sceneSubject" maxlength="200"></label><label>Visual purpose<textarea id="scenePurpose" maxlength="300"></textarea></label><label>Composition<input id="sceneComposition" maxlength="200"></label><label>On-screen text<input id="sceneText" maxlength="500"></label><label>Visual elements, one per line<textarea id="sceneElements"></textarea></label><div id="sceneNotice" class="notice" role="status"></div><div class="actions"><button class="small secondary" type="button" id="sceneCancel">Cancel</button><button class="small" id="sceneSave" type="submit">Create review draft</button></div></div></form></dialog><script>
(()=>{
  let parent=null, packageData=null, reviewedIdentity=null, directionData=null;
  const dialog=document.querySelector('#sceneDialog'), form=document.querySelector('#sceneForm'), select=document.querySelector('#sceneSelect'), notice=document.querySelector('#sceneNotice'), save=document.querySelector('#sceneSave');
  const fields={narration:document.querySelector('#sceneNarration'),visual_type:document.querySelector('#sceneLayout'),visual_subject:document.querySelector('#sceneSubject'),visual_purpose:document.querySelector('#scenePurpose'),composition:document.querySelector('#sceneComposition'),on_screen_text:document.querySelector('#sceneText'),visual_elements:document.querySelector('#sceneElements')};
  const close=()=>dialog.close();document.querySelector('#sceneClose').onclick=close;document.querySelector('#sceneCancel').onclick=close;
  function showDirection(){const d=directionData,box=document.querySelector('#sceneDirection');if(!d){box.textContent='Direction review unavailable.';return;}const warnings=d.warnings.filter(w=>!w.scene_id||w.scene_id===select.value);box.textContent='Direction review · '+(warnings.length?warnings.map(w=>w.message).join(' '):'No structural warnings for this scene; inspect the actual video.')+' '+(d.history_available?'Compared with '+d.recent_angles.length+' recent local briefs.':'No saved channel-angle context for this older video.')+' Advisory only; no layouts or approvals changed.';}
  function showScene(){if(!packageData)return;const scene=packageData.scene_plans.find(item=>item.scene_id===select.value),section=packageData.script_sections.find(item=>item.scene_id===select.value);if(!scene||!section){notice.textContent='This scene has no matching narration section.';save.disabled=true;return;}fields.narration.value=section.narration;if(!Array.from(fields.visual_type.options).some(option=>option.value===scene.visual_type)){fields.visual_type.add(new Option(scene.visual_type,scene.visual_type));}fields.visual_type.value=scene.visual_type;fields.visual_subject.value=scene.visual_subject||'';fields.visual_purpose.value=scene.visual_purpose||'';fields.composition.value=scene.composition||'';fields.on_screen_text.value=scene.on_screen_text||'';fields.visual_elements.value=(scene.visual_elements||[]).join('\n');save.disabled=false;notice.textContent='Edit one scene and create a new review draft.';showDirection();}
  // A scene's name is the heading shown on its card (falls back to the layout or the subject).
  function sceneName(item){const shown=((packageData&&packageData.reference_short&&packageData.reference_short.scenes)||[]).find(s=>s.scene_id===item.scene_id);return (shown&&(shown.heading||shown.headline))||item.visual_subject||String(item.visual_type||'scene').replace(/_/g,' ')}
  // The contact sheet is 4 tiles wide in scene order: label each tile and make it a button that selects that scene.
  function buildTiles(){const tiles=document.querySelector('#sceneTiles');tiles.replaceChildren();if(!packageData||!packageData.reference_short){document.querySelector('#sceneSheetHint').style.display='none';return}
    packageData.scene_plans.forEach((item,index)=>{const cell=document.createElement('button');cell.type='button';cell.dataset.scene=item.scene_id;cell.style.cssText='aspect-ratio:270/480;position:relative;background:transparent;border:2px solid transparent;border-radius:6px;padding:0;cursor:pointer;margin:0;min-width:0';
      const label=document.createElement('span');label.textContent=(index+1)+' · '+sceneName(item);label.style.cssText='position:absolute;left:4px;top:4px;right:4px;padding:2px 6px;border-radius:5px;background:rgba(8,15,31,.86);color:#fff;font:600 11px/1.3 system-ui;text-align:left;overflow:hidden;text-overflow:ellipsis;white-space:nowrap';
      cell.title='Scene '+(index+1)+' · '+sceneName(item);cell.setAttribute('aria-label','Edit scene '+(index+1)+', '+sceneName(item));cell.append(label);
      cell.onclick=()=>{select.value=item.scene_id;showScene();highlight()};tiles.append(cell)});highlight()}
  function highlight(){for(const cell of document.querySelectorAll('#sceneTiles button'))cell.style.borderColor=cell.dataset.scene===select.value?'#5ee8ff':'transparent'}
  select.onchange=()=>{showScene();highlight()};
  async function open(job){parent=job.id;packageData=null;reviewedIdentity=null;directionData=null;notice.textContent='Loading scene and approved script…';document.querySelector('#sceneDirection').textContent='Loading direction review…';select.replaceChildren();save.disabled=true;const sheet=document.querySelector('#sceneSheet');document.querySelector('#sceneSheetWrap').style.display='none';document.querySelector('#sceneSheetHint').style.display='none';document.querySelector('#sceneTiles').replaceChildren();sheet.removeAttribute('src');dialog.showModal();try{const response=await fetch(`/api/jobs/${job.id}/script`);if(!response.ok)throw Error(await response.text());const data=await response.json();packageData=data.package;reviewedIdentity=data.reviewed_identity;directionData=data.direction||null;for(const item of packageData.scene_plans){select.append(Object.assign(document.createElement('option'),{value:item.scene_id,textContent:'Scene '+(packageData.scene_plans.indexOf(item)+1)+' · '+sceneName(item)}));}if(job.artifacts.includes('contact_sheet_001')){sheet.src=`/api/jobs/${job.id}/artifacts/contact_sheet_001`;document.querySelector('#sceneSheetWrap').style.display='block';document.querySelector('#sceneSheetHint').style.display='block';buildTiles();}showScene();}catch(error){document.querySelector('#sceneDirection').textContent='Direction review unavailable.';notice.textContent='Could not load scene: '+error.message;}}
  form.onsubmit=async event=>{event.preventDefault();if(!parent||!reviewedIdentity||!packageData)return;save.disabled=true;save.textContent='Saving draft…';notice.textContent='Creating a new review draft…';const values={scene_id:select.value,expected_content_sha256:reviewedIdentity,actor:'local-dashboard',narration:fields.narration.value.trim(),visual_type:fields.visual_type.value,on_screen_text:fields.on_screen_text.value.trim(),visual_elements:fields.visual_elements.value.split('\n').map(value=>value.trim()).filter(Boolean)};for(const key of ['visual_subject','visual_purpose','composition']){const value=fields[key].value.trim();if(value)values[key]=value;}try{const response=await fetch(`/api/jobs/${parent}/scene-revisions`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(values)});if(!response.ok)throw Error(await response.text());const draft=await response.json();notice.textContent='Draft '+draft.job_id.slice(0,8)+' saved. Review and approve its exact script before rendering; the original video is unchanged.';save.textContent='Draft saved';}catch(error){notice.textContent='Could not create draft: '+error.message;save.disabled=false;save.textContent='Create review draft';}};
  async function decorate(){let jobs;try{const response=await fetch('/api/jobs');if(!response.ok)return;jobs=new Map((await response.json()).map(job=>[job.id,job]));}catch(_){return;}for(const card of document.querySelectorAll('.job[data-job-id]')){const job=jobs.get(card.dataset.jobId);if(!job||!job.artifacts.includes('content_package')||!['script_approval_required','preview_ready','final_ready','publication_approval_required'].includes(job.state)||card.querySelector('.scene-revision'))continue;const actions=card.querySelector('.actions');if(!actions)continue;const button=document.createElement('button');button.type='button';button.className='small secondary scene-revision';button.textContent='Revise one scene';button.onclick=()=>open(job);actions.append(button);}}
  decorate();setInterval(decorate,4000);
})();
</script>"""
